        """Verify login page elements are visible"""
        return (self.is_visible(self.selectors.USERNAME_INPUT) and 
                self.is_visible(self.selectors.PASSWORD_INPUT) and
                self.is_visible(self.selectors.LOGIN_BUTTON))
