## logger.py
```python
import logging
import os
from datetime import datetime

class Logger:
    _instance = None

    @classmethod
    def get_logger(cls, name: str = "IOTFramework"):
        """Get or create logger instance"""
        if cls._instance is None:
            cls._instance = cls._create_logger(name)
        return cls._instance

    @classmethod
    def _create_logger(cls, name: str):
        """Create logger with file and console handlers"""
        logger = logging.getLogger(name)
        logger.setLevel(logging.DEBUG)

        # Create logs directory if not exists
        os.makedirs("logs", exist_ok=True)

        # File handler
        log_file = f"logs/iot_framework_{datetime.now().strftime('%Y%m%d')}.log"
        file_handler = logging.FileHandler(log_file)
        file_handler.setLevel(logging.DEBUG)

        # Console handler
        console_handler = logging.StreamHandler()
        console_handler.setLevel(logging.INFO)

        # Formatter
        formatter = logging.Formatter(
            '%(asctime)s - %(name)s - %(levelname)s - %(message)s'
        )
        file_handler.setFormatter(formatter)
        console_handler.setFormatter(formatter)

        logger.addHandler(file_handler)
        logger.addHandler(console_handler)

        return logger
