from playwright.sync_api import Page, expect
from utils.logger import Logger
from utils.screenshot_manager import ScreenshotManager
from utils.angular_helpers import AngularHelpers
from config.config import Config

class BasePage:
    def __init__(self, page: Page):
        self.page = page
        self.logger = Logger.get_logger(self.__class__.__name__)
        self.screenshot_manager = ScreenshotManager(page)
        self.angular_helpers = AngularHelpers(page)
        self.config = Config()

    def navigate(self, url: str):
        """Navigate to URL with Angular stability check"""
        self.logger.info(f"Navigating to: {url}")
        self.page.goto(url, wait_until="networkidle")
        self.angular_helpers.wait_for_angular_stability()

    def click(self, selector: str, timeout: int = 30000):
        """Click element with Angular stability check"""
        self.logger.info(f"Clicking element: {selector}")
        self.angular_helpers.wait_for_angular_stability()
        self.page.click(selector, timeout=timeout)

    def fill(self, selector: str, value: str, timeout: int = 30000):
        """Fill input field"""
        self.logger.info(f"Filling {selector} with: {value}")
        self.page.fill(selector, value, timeout=timeout)

    def get_text(self, selector: str, timeout: int = 30000) -> str:
        """Get text content of element"""
        return self.page.text_content(selector, timeout=timeout)

    def is_visible(self, selector: str, timeout: int = 10000) -> bool:
        """Check if element is visible"""
        try:
            self.page.wait_for_selector(selector, state="visible", timeout=timeout)
            return True
        except:
            return False

    def wait_for_element(self, selector: str, state: str = "visible", timeout: int = 30000):
        """Wait for element to reach specific state"""
        self.page.wait_for_selector(selector, state=state, timeout=timeout)

    def take_screenshot(self, name: str):
        """Take screenshot"""
        self.screenshot_manager.take_screenshot(name)
