from pages.base_page import BasePage
from selectors.login_selectors import LoginSelectors

class LoginPage(BasePage):
    def __init__(self, page):
        super().__init__(page)
        self.selectors = LoginSelectors()

    def login(self, username: str, password: str):
        """Perform login operation"""
        self.logger.info(f"Attempting login with username: {username}")
        self.navigate(self.config.BASE_URL)
        self.fill(self.selectors.USERNAME_INPUT, username)
        self.fill(self.selectors.PASSWORD_INPUT, password)
        self.click(self.selectors.LOGIN_BUTTON)
        self.angular_helpers.wait_for_angular_stability()
        return DashboardPage(self.page)

    def is_login_page_loaded(self) -> bool:
        """Verify login page elements are visible"""
        return (self.is_visible(self.selectors.USERNAME_INPUT) and 
                self.is_visible(self.selectors.PASSWORD_INPUT) and
                self.is_visible(self.selectors.LOGIN_BUTTON))
