from playwright.sync_api import Page

class AngularHelpers:
    def __init__(self, page: Page):
        self.page = page

    def wait_for_angular_stability(self, timeout: int = 30000):
        """Wait for Angular to finish processing"""
        try:
            self.page.wait_for_function(
                """() => {
                    const el = document.querySelector('.cdk-overlay-container');
                    return !el || !el.children.length;
                }""",
                timeout=timeout
            )
        except:
            pass  # Continue even if Angular check times out

    def wait_for_http_requests(self, timeout: int = 30000):
        """Wait for pending HTTP requests to complete"""
        try:
            self.page.wait_for_load_state("networkidle", timeout=timeout)
        except:
            pass

    def is_angular_app(self) -> bool:
        """Check if page is an Angular application"""
        return self.page.evaluate("typeof window.getAllAngularRootElements === 'function'")
