from playwright.sync_api import Page, expect
import time

class WaitHelpers:
    def __init__(self, page: Page):
        self.page = page

    def wait_for_element_and_click(self, selector: str, timeout: int = 30000):
        """Wait for element to be visible and clickable, then click"""
        self.page.wait_for_selector(selector, state="visible", timeout=timeout)
        self.page.wait_for_selector(selector, state="attached", timeout=timeout)
        self.page.click(selector)

    def wait_for_table_data(self, table_selector: str, timeout: int = 30000):
        """Wait for table to have data rows"""
        self.page.wait_for_selector(table_selector, state="visible", timeout=timeout)
        self.page.wait_for_function(
            f"""() => {{
                const table = document.querySelector('{table_selector}');
                return table && table.querySelectorAll('tr').length > 1;
            }}""",
            timeout=timeout
        )

    def wait_for_loading_spinner_to_disappear(self, timeout: int = 30000):
        """Wait for Angular loading spinner to disappear"""
        try:
            self.page.wait_for_function(
                """() => {
                    const spinners = document.querySelectorAll('.mat-spinner, .loading-spinner');
                    return spinners.length === 0;
                }""",
                timeout=timeout
            )
        except:
            pass
