## Enhanced Logger with Context
```python
import logging
import os
import json
from datetime import datetime
from functools import wraps

class ContextLogger:
    def __init__(self, name: str):
        self.logger = logging.getLogger(name)
        self.context = {}

    def set_context(self, **kwargs):
        """Set logging context"""
        self.context.update(kwargs)

    def _format_message(self, msg: str) -> str:
        """Format message with context"""
        if self.context:
            context_str = json.dumps(self.context)
            return f"[{context_str}] {msg}"
        return msg

    def info(self, msg: str, **kwargs):
        self.logger.info(self._format_message(msg), **kwargs)

    def error(self, msg: str, **kwargs):
        self.logger.error(self._format_message(msg), **kwargs)

    def debug(self, msg: str, **kwargs):
        self.logger.debug(self._format_message(msg), **kwargs)

    def warning(self, msg: str, **kwargs):
        self.logger.warning(self._format_message(msg), **kwargs)

def log_step(func):
    """Decorator to log method execution"""
    @wraps(func)
    def wrapper(*args, **kwargs):
        logger = Logger.get_logger(func.__module__)
        logger.info(f"Executing: {func.__name__}")
        try:
            result = func(*args, **kwargs)
            logger.info(f"Completed: {func.__name__}")
            return result
        except Exception as e:
            logger.error(f"Failed: {func.__name__} - {str(e)}")
            raise
    return wrapper
```

## Logging Configuration
```python
# config/logging_config.yaml
version: 1
disable_existing_loggers: False

formatters:
  detailed:
    format: '%(asctime)s - %(name)s - %(levelname)s - %(message)s'
    datefmt: '%Y-%m-%d %H:%M:%S'

  json:
    format: '{"timestamp": "%(asctime)s", "logger": "%(name)s", "level": "%(levelname)s", "message": "%(message)s"}'

handlers:
  console:
    class: logging.StreamHandler
    level: INFO
    formatter: detailed
    stream: ext://sys.stdout

  file:
    class: logging.handlers.RotatingFileHandler
    level: DEBUG
    formatter: detailed
    filename: logs/iot_framework.log
    maxBytes: 10485760  # 10MB
    backupCount: 5

  error_file:
    class: logging.handlers.RotatingFileHandler
    level: ERROR
    formatter: detailed
    filename: logs/errors.log
    maxBytes: 10485760
    backupCount: 3

loggers:
  test:
    level: DEBUG
    handlers: [console, file]
    propagate: False

  page:
    level: DEBUG
    handlers: [console, file]
    propagate: False

root:
  level: INFO
  handlers: [console, file, error_file]
